const ChakraCard = ({ icon, label, color }) => {
    return (
        <div className="w-[96px] h-[96px] flex flex-col gap-[10px] items-center justify-center">
            {icon}

            <div className="min-w-[90px] h-[20px] flex items-center justify-center px-[10px]" style={{
                backgroundColor: color,
                clipPath: "path('M92.98 7.76984C92.04 6.01984 90.75 0.609844 83.91 0.589844H56.57H12.2C5.36 0.589844 4.07 6.00984 3.13 7.76984C2.19 9.51984 0 11.3298 0 11.3298C0 11.3298 2.18 13.1298 3.13 14.8898C4.07 16.6398 5.36 22.0598 12.2 22.0598H83.91C90.75 22.0598 92.04 16.6398 92.98 14.8898C93.92 13.1398 96.11 11.3298 96.11 11.3298C96.11 11.3298 93.93 9.52984 92.98 7.76984Z')"
            }}>
                <span className="text-white text-[12px] leading-[20px] font-semibold">
                    {label}
                </span>
            </div>
        </div>
    )
}

const GoalCard = ({ label }) => {
    return (
        <article className={"px-[10px] py-[15px] rounded-[100px] flex items-center gap-[10px] border border-white bg-white hover:border-[#D9B950]"}>
            <div className={"min-w-[62px] h-[62px] relative"}>
                <Image fill src={"/assets/goal_icon.png"} alt={"goal_icon"} />
            </div>

            <p className={"text-[20px] leading-[36px] text-jv-text-black"}>
                {label}
            </p>
        </article>
    )
}

const BenefitCard = ({ label, index }) => (
    <article className={`flex items-center gap-[20px] ${index <= 3 ? ' pr-[20px]' : 'flex-row-reverse justify-end'}`}>
        <p className="text-[20px] leading-relaxed text-jv-text-black">
            {label}
        </p>

        <div className="flex items-center justify-center min-w-[62px] w-[62px] h-[62px] relative bg-[url('/assets/benefit_index_icon.png')] bg-cover">
            <span className="text-[20px] leading-relaxed font-medium text-jv-red">
                {index}
            </span>
        </div>
    </article>
)
